package com.dexm.personajes.adapter.out.persistence;
import jakarta.persistence.*;
@Entity @Table(name="shield_inventory", uniqueConstraints=@UniqueConstraint(name="uk_shield_character",columnNames="character_id"))
public class ShieldEntity { @Id private String id; @Column(name="character_id",nullable=false) private String characterId; @Column(nullable=false) private String name; @Column(columnDefinition="text") private String description; @Column(name="hit_points",nullable=false) private int hitPoints; @Column(name="image_url",columnDefinition="longtext") private String imageUrl; protected ShieldEntity(){} public ShieldEntity(String id,String c,String n,String d,int p,String i){this.id=id;characterId=c;name=n;description=d;hitPoints=p;imageUrl=i;} public String getId(){return id;} public String getCharacterId(){return characterId;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public int getHitPoints(){return hitPoints;} public void setHitPoints(int v){hitPoints=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} }
